#pragma once

#include "ptv/ecs/World.h"
#include <nlohmann/json.hpp>
#include <string>
#include <algorithm>

namespace ptv {

struct LocomotionSettingsState {
    // toggles
    bool enable_teleport{true};
    bool enable_slide_head{false};
    bool enable_slide_controller{false};

    // turn
    std::string turn_mode{"snap"}; // "snap" | "smooth"
    float snap_angle_deg{45.0f};     // 30/45/60
    float smooth_turn_speed_degps{120.0f}; // 90..240

    // comfort + calibration
    float vignette_intensity{0.0f};  // 0..1
    float height_offset_m{0.0f};     // -0.3 .. +0.3
};

// Safe add-tag helper: ensures CTag exists and pushes a string tag.
inline void add_tag(World& w, std::uint32_t e, const std::string& s) {
    if (!w.has<CTag>(e)) {
        CTag t; t.tags.reserve(8); t.tags.push_back(s);
        w.emplace_or_replace<CTag>(e, std::move(t));
    } else {
        auto& t = w.get<CTag>(e);
        // avoid unbounded duplication of identical consecutive tags
        if (t.tags.empty() || t.tags.back() != s) {
            t.tags.push_back(s);
        }
    }
}

// Reads params for this mechanic (from its own CMechanicBinding entry) and fills state.
// Missing keys keep defaults; out-of-range values are clamped to spec.
inline void read_settings_from_params(const nlohmann::json& j, LocomotionSettingsState& out) {
    if (!j.is_object()) return;
    if (j.contains("enable_teleport")) out.enable_teleport = j.at("enable_teleport").get<bool>();
    if (j.contains("enable_slide_head")) out.enable_slide_head = j.at("enable_slide_head").get<bool>();
    if (j.contains("enable_slide_controller")) out.enable_slide_controller = j.at("enable_slide_controller").get<bool>();

    if (j.contains("turn_mode")) out.turn_mode = j.at("turn_mode").get<std::string>();
    if (out.turn_mode != "snap" && out.turn_mode != "smooth") out.turn_mode = "snap";

    if (j.contains("snap_angle_deg")) out.snap_angle_deg = j.at("snap_angle_deg").get<float>();
    // snap allowed: 30/45/60; snap to nearest
    {
        float cand = out.snap_angle_deg;
        float opts[3] = {30.0f, 45.0f, 60.0f};
        float best = 45.0f; float bd = 1e9f;
        for (float o: opts) { float d = std::abs(o - cand); if (d < bd) { bd = d; best = o; } }
        out.snap_angle_deg = best;
    }

    if (j.contains("smooth_turn_speed_degps")) out.smooth_turn_speed_degps = j.at("smooth_turn_speed_degps").get<float>();
    out.smooth_turn_speed_degps = std::clamp(out.smooth_turn_speed_degps, 90.0f, 240.0f);

    if (j.contains("vignette_intensity")) out.vignette_intensity = j.at("vignette_intensity").get<float>();
    out.vignette_intensity = std::clamp(out.vignette_intensity, 0.0f, 1.0f);

    if (j.contains("height_offset_m")) out.height_offset_m = j.at("height_offset_m").get<float>();
    out.height_offset_m = std::clamp(out.height_offset_m, -0.3f, 0.3f);

    // Safety: ensure at least one locomotion is enabled
    if (!out.enable_teleport && !out.enable_slide_head && !out.enable_slide_controller) {
        out.enable_teleport = true; // comfort-safe default
    }
}

// Extract this mechanic's params json (if present) from the binding entry list and parse.
inline nlohmann::json params_for_mechanic_from_binding(const CMechanicBinding& mb, const std::string& mech_id) {
    for (const auto& e : mb.entries) {
        // prefer explicit id match; fall back to builtin_id if used by tools
        if (e.id == mech_id || e.builtin_id == mech_id) {
            nlohmann::json j = nlohmann::json::parse(e.params_json, nullptr, false);
            if (j.is_discarded()) return nlohmann::json::object();
            return j;
        }
    }
    return nlohmann::json::object();
}

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <string>

#include "locomotion_options_ui_shared.h"

namespace ptv {

class LocomotionOptionsUI : public IMechanic {
public:
    void on_attach(World& w, std::uint32_t e, const nlohmann::json& params) override {
        entity_ = e;
        // Register Wrist Menu page via HUD/Wrist dependency contract
        add_tag(w, e, std::string("ui.page.register:{\"id\":\"locomotion\",\"title\":\"Locomotion\",\"order\":10}"));

        // Optional: seed from provided params on attach
        read_settings_from_params(params, target_);
        current_ = target_;
        height_current_ = current_.height_offset_m;

        // First-time hint toast (harmless if shown globally once)
        if (!hint_done_) {
            add_tag(w, e, std::string("ui.toast:{\"text\":\"Open Wrist Menu (X) to choose your locomotion\",\"ttl_s\":4.0}"));
            hint_done_ = true;
        }
    }

    void on_update(World& w, std::uint32_t e, float dt) override;

    void on_detach(World&, std::uint32_t) override {}

    std::string id() const override { return "generated.locomotion_options_ui"; }

    // Expose state to sibling files
    const LocomotionSettingsState& current() const { return current_; }

private:
    std::uint32_t entity_{0};
    LocomotionSettingsState current_{};
    LocomotionSettingsState target_{};
    LocomotionSettingsState last_published_{};

    float height_current_{0.0f};
    bool hint_done_{false};

    friend void apply_runtime(World& w, std::uint32_t e, float dt, LocomotionOptionsUI& self);
};

} // namespace ptv

PTV_REGISTER_MECHANIC("generated.locomotion_options_ui", ptv::LocomotionOptionsUI)

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <entt/entt.hpp>
#include <string>
#include <algorithm>

#include "locomotion_options_ui_shared.h"

namespace ptv {

static inline bool starts_with(const std::string& s, const char* pfx) {
    return s.rfind(pfx, 0) == 0;
}

// Tag prefixes from dependencies
static constexpr const char* kTagUIPageRegister = "ui.page.register:";
static constexpr const char* kTagUIToast        = "ui.toast:";
static constexpr const char* kTagMenuClose      = "ui.menu.close:";      // from HUD/Wrist
static constexpr const char* kTagSaveSection    = "save.section.push:";   // from SavePersistence
static constexpr const char* kTagSaveRequest    = "save.request:";       // from SavePersistence

// Our publish bus prefixes
static constexpr const char* kTagComfortVignette = "comfort.vignette:";   // consumed by overlays/flight/etc
static constexpr const char* kTagTurnState       = "locomotion.turn:";    // advertise turn mode + params
static constexpr const char* kTagLocoEnable      = "locomotion.enable:";  // request enabling a mechanic by id
static constexpr const char* kTagLocoDisable     = "locomotion.disable:"; // request disabling a mechanic by id
static constexpr const char* kTagActiveProfile   = "locomotion.active_profile:"; // small status chip
static constexpr const char* kTagHeightOffset    = "player.height_offset:";      // applied by rig/camera owner

// Serialize settings for persistence
static std::string settings_section_json(const LocomotionSettingsState& s) {
    nlohmann::json j{
        {"section","locomotion"},
        {"enable_teleport", s.enable_teleport},
        {"enable_slide_head", s.enable_slide_head},
        {"enable_slide_controller", s.enable_slide_controller},
        {"turn_mode", s.turn_mode},
        {"snap_angle_deg", s.snap_angle_deg},
        {"smooth_turn_speed_degps", s.smooth_turn_speed_degps},
        {"vignette_intensity", s.vignette_intensity},
        {"height_offset_m", s.height_offset_m}
    };
    return j.dump();
}

static void publish_changes(World& w, std::uint32_t e, const LocomotionSettingsState& cur, LocomotionSettingsState& last) {
    // Turn + comfort always pushed if changed
    if (cur.turn_mode != last.turn_mode || cur.snap_angle_deg != last.snap_angle_deg || cur.smooth_turn_speed_degps != last.smooth_turn_speed_degps) {
        nlohmann::json j{{"mode", cur.turn_mode}, {"snap_deg", cur.snap_angle_deg}, {"smooth_degps", cur.smooth_turn_speed_degps}};
        add_tag(w, e, std::string(kTagTurnState) + j.dump());
    }
    if (cur.vignette_intensity != last.vignette_intensity) {
        nlohmann::json j{{"intensity", cur.vignette_intensity}};
        add_tag(w, e, std::string(kTagComfortVignette) + j.dump());
    }

    // Locomotion enable/disable requests
    auto push_enable = [&](const char* id, bool en, bool prev){
        if (en != prev) {
            nlohmann::json j{{"id", id}};
            add_tag(w, e, std::string(en ? kTagLocoEnable : kTagLocoDisable) + j.dump());
        }
    };
    push_enable("builtin.locomotion.teleport", cur.enable_teleport, last.enable_teleport);
    push_enable("builtin.locomotion.slide.head_relative", cur.enable_slide_head, last.enable_slide_head);
    push_enable("builtin.locomotion.slide.controller_relative", cur.enable_slide_controller, last.enable_slide_controller);

    // Active profile status chip (priority: slide controller > slide head > teleport when multiple enabled)
    std::string profile = cur.enable_slide_controller ? "slide_controller" : (cur.enable_slide_head ? "slide_head" : "teleport");
    if (profile != (last.enable_slide_controller ? "slide_controller" : (last.enable_slide_head ? "slide_head" : "teleport"))) {
        nlohmann::json j{{"profile", profile}};
        add_tag(w, e, std::string(kTagActiveProfile) + j.dump());
    }

    last = cur;
}

static void maybe_persist_on_menu_close(World& w, std::uint32_t e, const LocomotionSettingsState& s) {
    if (!w.has<CTag>(e)) return;
    const auto& t = w.get<CTag>(e);
    bool saw_close = false;
    for (const auto& tag : t.tags) {
        if (starts_with(tag, kTagMenuClose)) { saw_close = true; break; }
    }
    if (saw_close) {
        // Push our section then request save
        add_tag(w, e, std::string(kTagSaveSection) + settings_section_json(s));
        add_tag(w, e, std::string(kTagSaveRequest) + std::string("{\"reason\":\"locomotion_options_changed\"}"));
    }
}

void LocomotionOptionsUI::on_update(World& w, std::uint32_t e, float dt) {
    // 1) Read current frame params from our binding entry (driven by tests / UI harness)
    if (w.has<CMechanicBinding>(e)) {
        const auto& mb = w.get<CMechanicBinding>(e);
        auto pj = params_for_mechanic_from_binding(mb, id());
        LocomotionSettingsState newTarget = target_;
        read_settings_from_params(pj, newTarget);
        target_ = newTarget;
    }

    // Safety: ensure one mode always on
    if (!target_.enable_teleport && !target_.enable_slide_head && !target_.enable_slide_controller) {
        target_.enable_teleport = true;
    }

    // 2) Smooth height offset application (no camera roll; clamped)
    float target_h = std::clamp(target_.height_offset_m, -0.3f, 0.3f);
    float lerp_rate = 8.0f; // 8 Hz critical damping-like
    float alpha = std::clamp(dt * lerp_rate, 0.0f, 1.0f);
    height_current_ = height_current_ + (target_h - height_current_) * alpha;
    if (std::abs(height_current_ - current_.height_offset_m) > 1e-4f) {
        current_.height_offset_m = height_current_;
        nlohmann::json j{{"meters", current_.height_offset_m}};
        add_tag(w, e, std::string(kTagHeightOffset) + j.dump());
    }

    // 3) Copy immediate settings (non-height) and publish changes
    current_.enable_teleport = target_.enable_teleport;
    current_.enable_slide_head = target_.enable_slide_head;
    current_.enable_slide_controller = target_.enable_slide_controller;
    current_.turn_mode = target_.turn_mode;
    current_.snap_angle_deg = target_.snap_angle_deg;
    current_.smooth_turn_speed_degps = target_.smooth_turn_speed_degps;
    current_.vignette_intensity = target_.vignette_intensity;

    publish_changes(w, e, current_, last_published_);

    // 4) Persist when menu closes
    maybe_persist_on_menu_close(w, e, current_);
}

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <string>

#include "locomotion_options_ui_shared.h"

// This file intentionally left minimal; the first-time toast is posted from on_attach
// in the register.cpp to ensure it fires as soon as the rig spawns. This TU exists to
// keep the suggested split and leave room for future scene-conditional hints.
